using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GainOtherEffectEffect", menuName = "Data/Battle/Effects/Orion/GainOtherEffect Effect")]
public class GainOtherEffectEffect : Effect
{
	private const string inscriptionBaseID = "InscriptionBase";

	[Header("Gain Other Effect Effect")]
	[SerializeField]
	private DefaultEffectAction effectAction;

	[SerializeField]
	private bool celestialRegret;

	[SerializeField]
	[ShowIf("celestialRegret")]
	private KarmaEffect karmaEffect;

	[SerializeField]
	[HideIf("celestialRegret")]
	private ActivateStarAbility activateStarAbility;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		if (amount == EffectsValues.NO_VALUE)
		{
			amount = -1;
		}
		text = ((!celestialRegret) ? GetInscriptionBaseDescription(activateStarAbility, effectAction.GetActionDescription(amount).LowercaseFirst()) : GetKarmaActivatedBaseDescription(effectAction.GetActionDescription(amount).LowercaseFirst()));
		return text + AppendedDescription();
	}

	public string GetKarmaActivatedBaseDescription(string afterKarmaActivatedDescription)
	{
		return Smart.Format(base.localizationManager.GetLocalizedWhenTriggered(), karmaEffect.GetEffectName(), afterKarmaActivatedDescription);
	}

	public string GetInscriptionBaseDescription(ActivateStarAbility activateStarAbilityExternal, string afterInscriptionBaseDescription)
	{
		return Smart.Format(base.localizationManager.GetLocalizedString("InscriptionBase"), activateStarAbilityExternal.GetLocalizedNameWithoutModifiers(), afterInscriptionBaseDescription, activateStarAbilityExternal.StarAbilityID);
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectAction.CastTargetAmount(effectOwner, effectAmount, null);
		return effectAmount;
	}
}
